import{_ as a,o as i,c as n,a3 as t}from"./chunks/framework.BveOjhN0.js";const c=JSON.parse('{"title":"懒猫算力仓X3系统升级","description":"","frontmatter":{"title":"懒猫算力仓X3系统升级","date":"2026-09-08T16:09:19.000Z","categories":"Home","tags":["网络"]},"headers":[],"relativePath":"posts/懒猫算力仓X3系统升级.md","filePath":"posts/懒猫算力仓X3系统升级.md","lastUpdated":null}'),e={name:"posts/懒猫算力仓X3系统升级.md"};function p(l,s,h,r,o,k){return i(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h1><p>作为第一批支持懒猫算力仓的用户，可以看前一篇 <a href="https://blog.white-alone.com/posts/%E5%AE%B6%E5%BA%AD%E7%AE%97%E5%8A%9B%E4%B8%AD%E5%BF%83%E2%80%94%E6%87%92%E7%8C%AB%E7%AE%97%E5%8A%9B%E4%BB%93" target="_blank" rel="noreferrer">《家庭算力中心—懒猫算力仓》</a>，但自从新一代基于Thor的X5出来以后，X3就成牛夫人了。 JetPack 7.x 相比于 JetPack 6.x 是一次重大的平台级迁移与跨代升级，NVIDIA官方出了Jetson 7.2.x后，我自己的Orin AGX 64G就升级了，新的sdk兼容、超频都很舒服，但懒猫算力仓的升级就一直都没跟上。在VIP群里push了N次终于给了刷机包 <a href="https://pan.baidu.com/s/1HyPb8XP3mR4KFAQckPDHEQ?pwd=zyxt" target="_blank" rel="noreferrer">T912_JP7.2</a> 可以升级到7.2.0了。</p><h1 id="升级原理" tabindex="-1">升级原理 <a class="header-anchor" href="#升级原理" aria-label="Permalink to &quot;升级原理&quot;">​</a></h1><p>懒猫算力仓X3本质其实是一块Nvidia Jetson Orin AGX 64G的三方载板，优化了散热，加了2个nvme口、万兆网口等，可以很方便的使用，在搭配他们自研的APP，能够很方便的挂在到懒猫微服上，搭配各种应用。在淘宝平台也能买到很多类似的三方载板。 <img src="https://raw.githubusercontent.com/white-alone/blog_img/master/%E6%87%92%E7%8C%AB%E7%AE%97%E5%8A%9B%E4%BB%93X3%E7%B3%BB%E7%BB%9F%E5%8D%87%E7%BA%A7/1788857770261.png" alt="enter description here"> 懒猫官方文档里的<a href="https://developer.lazycat.cloud/aipod/os/flash-jetson-rc2.html" target="_blank" rel="noreferrer">算力舱刷系统（新版）</a> 目前还是jetson 6.x的，所以如果要想使用 jetson 7.x，就得需要更新官方的基础系统，同时要更新载板的BSP包，因为硬件和官方不同，驱动的dts也不同。</p><p>Jetson 6.x的系统是ubuntu 22.04，到了7.x 就是Ubuntu 24.04了，如果是官方的Orin开发板，可以用SDK生成iso镜像或者u盘镜像，直接u盘安装就可以了，但懒猫X3这样的三方载板这样是不可行的，我测试过，系统能装上，但SSD不认了，所以必须要在烧录系统时候将驱动加载进去，和传统的嵌入式Linux区别不大。</p><p>==需要注意的是，升级完成后，会都是原有EMMC上数据，不影响SSD数据，之后只能当一台Jetson Orin AGX 64G开发板用，因为懒猫官方的应用适配还没做，无法用懒猫微服直接连接和控制了！！！ #F44336==</p><h1 id="升级操作" tabindex="-1">升级操作 <a class="header-anchor" href="#升级操作" aria-label="Permalink to &quot;升级操作&quot;">​</a></h1><p>下载nvidia官方的包，当前最新是7.2.1，下载BSP包和Sample Root FileSystem <a href="https://developer.nvidia.com/embedded/jetpack-archive" target="_blank" rel="noreferrer">https://developer.nvidia.com/embedded/jetpack-archive</a><img src="https://raw.githubusercontent.com/white-alone/blog_img/master/%E6%87%92%E7%8C%AB%E7%AE%97%E5%8A%9B%E4%BB%93X3%E7%B3%BB%E7%BB%9F%E5%8D%87%E7%BA%A7/1788857997216.png" alt="enter description here"><img src="https://raw.githubusercontent.com/white-alone/blog_img/master/%E6%87%92%E7%8C%AB%E7%AE%97%E5%8A%9B%E4%BB%93X3%E7%B3%BB%E7%BB%9F%E5%8D%87%E7%BA%A7/1788858088473.png" alt="enter description here"> 再从百度网盘下载T912_JP7.2里的包 <img src="https://raw.githubusercontent.com/white-alone/blog_img/master/%E6%87%92%E7%8C%AB%E7%AE%97%E5%8A%9B%E4%BB%93X3%E7%B3%BB%E7%BB%9F%E5%8D%87%E7%BA%A7/1788858239096.png" alt="enter description here"></p><p>之后准备一台Ubuntu 24.04系统的机器，可以是虚拟机也可以是物理机，空余空间最少50G，将下载下来的压缩包都传到机器上/data目录，就可以开始了。</p><p>切换到root用户执行，比较省事</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">su</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/orin_7.2.1_x3</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/orin_7.2.1_x3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xvf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/Jetson_Linux_R39.2.1_aarch64.tbz2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xpf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Tegra_Linux_Sample-Root-Filesystem_R39.2.1_aarch64.tbz2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Linux_for_Tegra/rootfs/</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Linux_for_Tegra/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./tools/l4t_flash_prerequisites.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./apply_binaries.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --openrm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/Tw_Rootfs_R39.2.0_V1.0.0.tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/bsp-twsetup-T912_v1.2-jp7.2.0_v1.0.0-release-v1.0.0-20260723_183409.tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xvf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bsp-twsetup-T912_v1.2-jp7.2.0_v1.0.0-release-v1.0.0-20260723_183409.tar</span></span></code></pre></div><p>这时候如果执行百度网盘里的jp7.2flash.docx文档中的<code>./twsetup/install.sh</code>命令，会报错，因为这个厂家patch脚本只针对7.2做了适配，7.2.1不行。 我对比了下Jetson 7.2.1和7.2.0的kernel，发现内核版本没有变化，虽然厂家给的是编译完成的文件，不是源码，但如果内核变变化，7.2.1也可以直接用，所以做了patch包 jetpack-7.2.1-x3-version-gates.patch</p><div class="language-patch vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">patch</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>diff --git a/twsetup/install.sh b/twsetup/install.sh</span></span>
<span class="line"><span>--- a/twsetup/install.sh</span></span>
<span class="line"><span>+++ b/twsetup/install.sh</span></span>
<span class="line"><span>@@ -188 +188 @@</span></span>
<span class="line"><span>-	&quot;39.2.0&quot;)</span></span>
<span class="line"><span>+	&quot;39.2.0&quot;|&quot;39.2.1&quot;)</span></span>
<span class="line"><span>diff --git a/twsetup/env.sh b/twsetup/env.sh</span></span>
<span class="line"><span>--- a/twsetup/env.sh</span></span>
<span class="line"><span>+++ b/twsetup/env.sh</span></span>
<span class="line"><span>@@ -6 +6 @@</span></span>
<span class="line"><span>-L4T=&quot;39.2.0&quot;</span></span>
<span class="line"><span>+L4T=&quot;39.2.1&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># The same env.sh change must also be applied inside the device-side</span></span>
<span class="line"><span># bsp-twsetup tar archive before rebuilding and renaming it for jp7.2.1.</span></span></code></pre></div><p>打完patch就可以了</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/orin_7.2.1_x3/Linux_for_Tegra</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">patch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/jetpack-7.2.1-x3-version-gates.patch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./twsetup/install.sh</span></span></code></pre></div><p>执行完成后，打开算力仓X3的底盖，按住Rec按钮，再按Reset按钮，让算力仓X3进入Recovery模式，用一根质量好的C口数据线连接电脑和算力仓，如果是虚拟机，记得将虚拟机的usb控制器设置为3.x，然后挂上算力仓usb设备，就可以刷机了。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./flash.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jetson-agx-orin-devkit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> internal</span></span></code></pre></div><p>经过漫长的等待，刷机完成后，重启即可。</p><p><img src="https://raw.githubusercontent.com/white-alone/blog_img/master/%E6%87%92%E7%8C%AB%E7%AE%97%E5%8A%9B%E4%BB%93X3%E7%B3%BB%E7%BB%9F%E5%8D%87%E7%BA%A7/1788859693453.png" alt="enter description here"></p><h1 id="后记" tabindex="-1">后记 <a class="header-anchor" href="#后记" aria-label="Permalink to &quot;后记&quot;">​</a></h1><p>现在懒猫官方一直在更新算力仓X5的各种应用，算力仓X3的用户只能干瞪眼，刷机升级后，就当一台普通的Orin开发板用也还行，275T算力64G显存，跑很多小模型还是OK的，比如我做了个电子元件的管理系统，家里的电子元件太多了，做的电路板、开发板也多，管理起来很麻烦，用app直接拍照识别电子元件然后录入系统，整理和管理都非常方便。</p>`,21)])])}const g=a(e,[["render",p]]);export{c as __pageData,g as default};
